import{_ as t,o as a,c as d,X as o}from"./chunks/framework.pSp8ynCZ.js";const u=JSON.parse('{"title":"Plans and costs: opt","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/api/reference-opt.md","filePath":"reference-opt.md"}'),r={name:"rust/api/reference-opt.md"};function c(s,e,n,i,l,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="plans-and-costs-opt" tabindex="-1">Plans and costs: opt <a class="header-anchor" href="#plans-and-costs-opt" aria-label="Permalink to &quot;Plans and costs: opt&quot;">​</a></h1><p><code>cellpack::opt</code> represents cache residency, compiler options, machine costs, modeled loads and serial reference policies. The application&#39;s bound <code>Loader</code> supplies the graph and high-level compilation entry points. The runtime executes the resulting plan; it does not choose a separate online eviction policy on each cache lookup.</p><h2 id="compilation-and-replay" tabindex="-1">Compilation and replay <a class="header-anchor" href="#compilation-and-replay" aria-label="Permalink to &quot;Compilation and replay&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Loader method</th><th>Input</th><th>Return / effect</th></tr></thead><tbody><tr><td><code>plan_options</code></td><td>Cache bytes</td><td>Options with loader-derived gap and default costs</td></tr><tr><td><code>compile</code></td><td>Stored <code>&amp;[CellId]</code>, options</td><td>Owned offline <code>Plan</code></td></tr><tr><td><code>replay</code></td><td>Plan and exact stored sequence</td><td><code>PlanSummary</code> without record loading</td></tr><tr><td><code>replay_with_cost</code></td><td>Same plus another cost model</td><td>Repriced summary, unchanged decisions</td></tr><tr><td><code>compile_online</code></td><td>Stored sequence, finite-horizon options</td><td>Collected plan and <code>OnlineStats</code></td></tr><tr><td><code>plan_online</code></td><td>General <code>Accesses</code>, options</td><td>Online compiler statistics without loading</td></tr><tr><td><code>online</code></td><td>Validated options</td><td><code>Planning::Online</code> for a run</td></tr></tbody></table><p>Offline plans require a stored sequence within the implementation&#39;s access-count bound. Online planning accepts computed sequences and bounded lookahead. Compiler thread count affects sharding and can affect decisions; scheduling order of the same compilation does not define the policy.</p><h2 id="planoptions" tabindex="-1">PlanOptions <a class="header-anchor" href="#planoptions" aria-label="Permalink to &quot;PlanOptions&quot;">​</a></h2><p><a href="/cellpack-docs/rust/docs/planning.html">Planning</a> lists all fields and defaults. The most important unit distinction is <code>gap/horizon</code> in <strong>slots</strong>, while <code>chunk</code> is in <strong>accesses</strong>. A slot contains <code>slot_cells × schemas</code> accesses. The execution window cannot exceed the reuse gap; horizon cannot be shorter than that gap.</p><table tabindex="0"><thead><tr><th>Choice</th><th>Contract</th></tr></thead><tbody><tr><td><code>PlanObjective::Misses</code></td><td>Page-only miss objective; decoded-row caching is off</td></tr><tr><td><code>PlanObjective::Time</code></td><td>Minimize modeled time under declared costs</td></tr><tr><td><code>rows = true</code></td><td>Requires a cost model and time objective</td></tr><tr><td><code>RowPolicy::Incremental</code></td><td>Online/offline reuse-interval decisions</td></tr><tr><td><code>RowPolicy::Global</code></td><td>Offline whole-sequence row reference</td></tr><tr><td><code>block_pages</code></td><td>Optional merged admission size; requires costs</td></tr><tr><td><code>cache_bytes</code></td><td>Planned frame budget, not total RSS</td></tr></tbody></table><p>Rows retain stored dtype and standard ids. Their size includes decompressed payload and page rounding. Process outputs are not cached.</p><h2 id="plan-and-residency" tabindex="-1">Plan and Residency <a class="header-anchor" href="#plan-and-residency" aria-label="Permalink to &quot;Plan and Residency&quot;">​</a></h2><p><code>Plan</code> contains immutable residency and frame assignments plus compatibility identities. <code>Residency</code> describes an <code>Object::Page</code> or <code>Object::Row</code>, its admission and last use, and assigned frame extent. <code>frames_of</code> resolves its frame list.</p><table tabindex="0"><thead><tr><th>Plan query</th><th>Meaning</th></tr></thead><tbody><tr><td><code>len / schemas / slot_cells</code></td><td>Bound sequence and output layout</td></tr><tr><td><code>reuse_gap / distance</code></td><td>Reservation gap in slots / accesses</td></tr><tr><td><code>cache_bytes / cache_frames</code></td><td>Frame capacity</td></tr><tr><td><code>cost / summary</code></td><td>Optional model and compiled summary</td></tr><tr><td><code>residencies / frames_of</code></td><td>Immutable planned contents</td></tr><tr><td><code>write / open</code></td><td>Binary file persistence</td></tr><tr><td><code>to_bytes / from_bytes</code></td><td>Owned byte representation</td></tr></tbody></table><p><code>CPKPLAN1</code> plans bind to inputs, mappings, schemas, process identities, slot size and exact access contents. <code>prepare</code> checks compatibility before execution. A serialized plan is not a portable promise of identical throughput on different hardware. Keep process identities synchronized with callback/configuration changes.</p><h2 id="costmodel-and-resource-accounting" tabindex="-1">CostModel and resource accounting <a class="header-anchor" href="#costmodel-and-resource-accounting" aria-label="Permalink to &quot;CostModel and resource accounting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Describes</th></tr></thead><tbody><tr><td>Capacity</td><td>Physical worker cores, device IOPS/bandwidth, memory bandwidth, overlap share</td></tr><tr><td><code>InputCost</code></td><td>Per-record, per-element and cold-chunk decode work</td></tr><tr><td><code>RowCost</code></td><td>Per-payload-byte gather and row-admission work</td></tr><tr><td><code>OutputCost</code></td><td>Mapping, filling, processing and partial-row costs per schema</td></tr><tr><td><code>ProcessCost</code></td><td>Process-size bands ending at declared maximum elements</td></tr><tr><td><code>convert</code></td><td>Per-element cost per loader <code>Conversion</code> class</td></tr><tr><td><code>Loads</code></td><td>Requests, device bytes, core-seconds and memory traffic</td></tr><tr><td><code>Prices</code></td><td>Marginal values used to compare reuse candidates</td></tr></tbody></table><p>Operation costs use core-seconds; capacity converts them into modeled wall time. Output-cost order must match schema order. <code>seconds</code>, <code>service</code> and <code>prices</code> operate on a load vector; their outputs are model results, not measurements.</p><p><code>CostModel::defaults</code> provides hardware-tier defaults; <code>opt::defaults::model</code> and <code>Tier</code> select those defaults explicitly. Calibration records are managed by the application. Binary <code>to_bytes/from_bytes</code> is available without Serde; optional <code>serde</code> adds structured serialization derives.</p><p><code>PlanSummary</code> reports replay work and modeled time. <code>OnlineStats</code> reports compiler progress and its corresponding work. See <a href="/cellpack-docs/rust/docs/profiling.html">profiling</a> for the current time formula and measured counters.</p><h2 id="serial-page-reference" tabindex="-1">Serial page reference <a class="header-anchor" href="#serial-page-reference" aria-label="Permalink to &quot;Serial page reference&quot;">​</a></h2><p><code>PageTrace::from_source</code> extracts page uses for a stored sequence; <code>from_pages</code> constructs a synthetic trace. <code>page_uses</code> and <code>distinct_pages</code> describe it; <code>optimum(capacity_pages)</code> returns a page-only <code>CacheSummary</code>.</p><p>This optimal reference has serial page semantics and bypass. It does not include decoded rows, concurrency reservation gaps, sharding, or finite lookahead. Do not describe every production page-and-row plan as globally optimal.</p><h2 id="complete-interface-index" tabindex="-1">Complete interface index <a class="header-anchor" href="#complete-interface-index" aria-label="Permalink to &quot;Complete interface index&quot;">​</a></h2><h3 id="re-exports" tabindex="-1">Re-exports <a class="header-anchor" href="#re-exports" aria-label="Permalink to &quot;Re-exports&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-opt-defaults-enum-Tier.html"><code>Tier</code></a></td><td>A class of storage, for its default device rates.</td></tr></tbody></table><h3 id="structs" tabindex="-1">Structs <a class="header-anchor" href="#structs" aria-label="Permalink to &quot;Structs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-CacheSummary.html"><code>CacheSummary</code></a></td><td>What a serial run of a trace did: its page uses, and the hits and misses a capacity produced.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-CostModel.html"><code>CostModel</code></a></td><td>The loader’s resources on one machine and the work it does per access, record, element, request and cached-row byte. Work is in core-seconds: seconds of one physical core (two workers sharing a core through SMT take it together).</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-InputCost.html"><code>InputCost</code></a></td><td>Decoding records: core-seconds per record, per stored element and per record whose chunk is cold.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-Loads.html"><code>Loads</code></a></td><td>What a window of accesses takes from each resource.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-OnlineStats.html"><code>OnlineStats</code></a></td><td>What an online compilation did.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-OutputCost.html"><code>OutputCost</code></a></td><td>What one output schema’s delivery costs, per element, per row and per call.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-PageTrace.html"><code>PageTrace</code></a></td><td>Canonical page requests: cells in access order, each cell’s pages in file order. This serial reference has no execution window, reuse-gap reservation or management cost.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-Plan.html"><code>Plan</code></a></td><td>A cache plan: the residencies a compilation chose, the frames they hold, and what they were compiled for.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-PlanOptions.html"><code>PlanOptions</code></a></td><td>What a compilation optimizes for: the budget, the reuse gap, the objective and the cost model of one loader on one machine.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-PlanSummary.html"><code>PlanSummary</code></a></td><td>The serial execution of a plan, as an independent replay counts it.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-Prices.html"><code>Prices</code></a></td><td>Marginal seconds of a window’s modeled time per unit of each load: the gradient of a smoothed T at the loads it was taken at. Saving loads x is worth prices.value(x) seconds.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-ProcessCost.html"><code>ProcessCost</code></a></td><td>One band of a process function’s size curve: the costs that hold for a row of up to max_elements elements.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-Residency.html"><code>Residency</code></a></td><td>One residency: an object held from its admission through its last use.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-struct-RowCost.html"><code>RowCost</code></a></td><td>Cached rows: core-seconds of gathering one into a worker’s scratch and of building and writing one, both per payload byte.</td></tr></tbody></table><h3 id="enums" tabindex="-1">Enums <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-opt-enum-Object.html"><code>Object</code></a></td><td>A cached object.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-enum-PlanObjective.html"><code>PlanObjective</code></a></td><td>What a compilation minimizes.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-enum-RowPolicy.html"><code>RowPolicy</code></a></td><td>Row selection of page+row compilations.</td></tr></tbody></table><h3 id="constants" tabindex="-1">Constants <a class="header-anchor" href="#constants" aria-label="Permalink to &quot;Constants&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-opt-constant-DEFAULT_CHUNK.html"><code>DEFAULT_CHUNK</code></a></td><td>Default compilation chunk in accesses.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-constant-DEFAULT_COMPILE_THREADS.html"><code>DEFAULT_COMPILE_THREADS</code></a></td><td>Default compiler threads: a fixed count, not derived from the machine.</td></tr></tbody></table><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-opt-fn-access_fingerprint.html"><code>access_fingerprint</code></a></td><td>Identity of an access sequence, checked before a plan is used.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-fn-default_distance.html"><code>default_distance</code></a></td><td>Default execution window in accesses for a worker count and in-flight depth: four times the accesses in flight.</td></tr></tbody></table><h2 id="default-model-api" tabindex="-1">Default-model API <a class="header-anchor" href="#default-model-api" aria-label="Permalink to &quot;Default-model API&quot;">​</a></h2><h3 id="structs-1" tabindex="-1">Structs <a class="header-anchor" href="#structs-1" aria-label="Permalink to &quot;Structs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-opt-defaults-struct-Host.html"><code>Host</code></a></td><td>The host’s worker costs and memory bandwidth.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-defaults-struct-Storage.html"><code>Storage</code></a></td><td>Device rates of a tier and its per-request worker cost.</td></tr></tbody></table><h3 id="enums-1" tabindex="-1">Enums <a class="header-anchor" href="#enums-1" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-opt-defaults-enum-Tier.html"><code>Tier</code></a></td><td>A class of storage, for its default device rates.</td></tr></tbody></table><h3 id="constants-1" tabindex="-1">Constants <a class="header-anchor" href="#constants-1" aria-label="Permalink to &quot;Constants&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-opt-defaults-constant-BUCKET.html"><code>BUCKET</code></a></td><td>Accesses per priced window.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-defaults-constant-HOST.html"><code>HOST</code></a></td><td>Worker costs of the reference machine, in core-seconds.</td></tr></tbody></table><h3 id="functions-1" tabindex="-1">Functions <a class="header-anchor" href="#functions-1" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-opt-defaults-fn-builtin.html"><code>builtin</code></a></td><td>The built-in dense output.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-defaults-fn-process.html"><code>process</code></a></td><td>A process function nothing was measured for.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-opt-defaults-fn-storage.html"><code>storage</code></a></td><td>The stored rates of a tier: sustained random reads, and the loader’s per-request cost measured on the reference machine.</td></tr></tbody></table>',41)])])}const m=t(r,[["render",c]]);export{u as __pageData,m as default};
